"""GENERATED by tools/gen.py from sheets/*.json - edit the sheets, not this file."""

class ACTUAL_PLAYER:
    VTABLE = 0x0  # rtti:.?AVACTUAL_PLAYER@db@@: primary vtable; instances found by heap scan (34,993 in lab save, stride 0x3E8)
    CONTRACTED_TEAM = 0x130  # ptr:TEAM: team the player is registered to (first team / U21 / U18)
    WEIGHT_KG = 0x14c  # u8: weight in kg
    HEIGHT_CM = 0x14e  # u16: height in cm
    CURRENT_ABILITY = 0x200  # u16: CA 1-200
    POTENTIAL_ABILITY = 0x202  # u16: PA 1-200
    POSITION_RATINGS = 0x208  # u8[15]: position familiarity 1-20 per slot (slot order in sheet fm_positions)
    ATTRIBUTES = 0x217  # u8[54]: attributes 1-100, order in sheet fm_attributes
    DATE_OF_BIRTH = 0x2bc  # fm_date: u16 day-of-year (low 9 bits) + u16 year
    FIRST_NAME = 0x2d0  # fm_name_ref: ptr to name-table entry; *entry = ptr to {u32 len, utf8}
    SECOND_NAME = 0x2d8  # fm_name_ref: surname
    COMMON_NAME = 0x2e0  # fm_name_ref: single/common name (e.g. Marquinhos); 0 if none
    NATION = 0x2e8  # ptr:NATION: nationality
    PERSON_ID = 0x280  # u32: unique person id; used by match event lists and GAME_MATCH_PLAYER_STATS

class TEAM:
    VTABLE = 0x0  # rtti:.?AVTEAM@db@@: team (first team, reserves, youth); stride 0xB8
    CLUB = 0x30  # ptr:CLUB: owning club

class CLUB:
    VTABLE = 0x0  # rtti:.?AVCLUB@db@@: club
    NAME = 0xc0  # fm_string: ptr to {u32 len, utf8}
    SHORT_NAME = 0xc8  # fm_string: short name
    UNIQUE_ID = 0xc  # u32: FM's club unique id (graphics/pictures/club/<id>/logo in logo config.xml)

class FIXTURE:
    VTABLE = 0x0  # rtti:.?AVFIXTURE@sicomps@@: scheduled fixture (FIXTURE_RESULT@sicomps shares the layout once played)
    HOME_TEAM = 0x8  # ptr:TEAM: home team
    AWAY_TEAM = 0x10  # ptr:TEAM: away team
    DATE = 0x4c  # fm_date: match date

class GAME_MATCH:
    VTABLE = 0x0  # rtti:.?AVGAME_MATCH@@: the human club's match being played today; exists from team news until after full time
    ROSTER = 0xcea8  # ptr:MATCH_PLAYER[]: both match squads in one list: home squad first, then away, null after the last (read up to 64; the squad size depends on the competition's substitutes rule). Group players by MATCH_PLAYER.match_team -> MATCH_TEAM.team; the first player's team is home. (MATCH_PLAYER+0x1ec looked like a side flag but flipped between sessions - not used)

class MATCH_PLAYER:
    VTABLE = 0x0  # rtti:.?AVMATCH_PLAYER@simatch@@: per-player match record, stride 0x1880
    ACTUAL_PLAYER_SUB = 0x28  # ptr:ACTUAL_PLAYER+0x278: points at ACTUAL_PLAYER secondary base; subtract 0x278
    FULL_NAME = 0x30  # fm_string: display name
    SHEET_SLOT = 0x6bb  # u8: team-sheet slot 0-10 starters, 11+ subs (11-17 with 7 subs; up to 25 seen: Liverpool v Galatasaray named 15 subs)
    MATCH_TEAM = 0x1d0  # ptr:MATCH_TEAM: the player's side in this match (+0x1d8 = opponent)
    ATTRIBUTES = 0x397  # u8[54]: match engine copy of the 54 attributes (same order as fm_attributes); present for VIRTUAL_PLAYERs too
    GOAL_INVOLVEMENTS = 0x4cc  # u32: 1 for scorer and assister after first goal (not separated yet)

class FIXTURE_RESULT:
    VTABLE = 0x0  # rtti:.?AVFIXTURE_RESULT@sicomps@@: result record of a fixture; several copies per fixture (same +0x08/+0x10/+0x4c), one is the live copy the match engine updates
    HOME_GOALS = 0x64  # u8: home goals; 0xff = not played. Live copy counts up during FM's match
    AWAY_GOALS = 0x68  # u8: away goals; 0xff = not played
    STATE = 0x6c  # u8: 0 = unplayed / in play; nonzero (0x0a, u16 0x010a) = finished. Every copy of the fixture is finished and carries the live copy's score once you leave the match
    AUTHORITATIVE_SCORE = 0x64  # u8 pair (+0x64 home, +0x68 away): FM commits the score from the live FIXTURE_RESULT copy when you leave the match. Write the SPFL26 score into every copy of today's fixture whose state is finished, before and after leaving
    EVENTS = 0x70  # ptr:EVENT_VECTOR: -> {begin, end, cap} of 8-byte events {u32 person id, u8 side 0 home/1 away, u8 type 0 goal/2 pen/3 sent off, u16 minute}; each copy has its own

class MATCH_TEAM:
    TEAM = 0x48  # ptr:TEAM: club team of this side (works for clubs whose players are all VIRTUAL_PLAYERs)

class HUMAN_NON_PLAYER:
    VTABLE = 0x0  # rtti:.?AVHUMAN_NON_PLAYER@db@@: a human manager (you); 2 instances in the lab save, one employed
    CONTRACT = 0x518  # ptr:FULL_CONTRACT: current job contract (null when unemployed)

class FULL_CONTRACT:
    TEAM = 0x10  # ptr:TEAM: the club team you manage

class PLAYER:
    PERSON_ID = 0x8  # u32: person id read through MATCH_PLAYER.actual_player_sub (the PLAYER sub-object, ACTUAL_PLAYER +0x278); also set for VIRTUAL_PLAYER (fictional squad fillers) and ACTUAL_PLAYER_AND_NON_PLAYER (player-coaches), which have no ACTUAL_PLAYER layout

class GAME_MATCH_PLAYER_STATS:
    PERSON_ID = 0x10  # u32: person id of the player (0x100-byte records, arrays per club in team-sheet order)
    RATING_X100 = 0x78  # u16: match rating x100 (6.85 = 685)
    GOALS = 0x7f  # u8: goals in this match
    YELLOW_CARDS = 0x9a  # u8: yellow cards in this match

